function normalizeLanguage(value){
 if (/^it(?:-IT)?$/i.test(value)) return 'it';
 if (/^zh-(hk|tw|hant)$/i.test(value)) return 'zh-HK';
 return /^(zh|cn|zh-cn|zh-hans)$/i.test(value) ? 'zh' : 'en';
}
